#!/usr/bin/env python3
"""What `pr_status.py` decides, on fixed data.

Run: python3 -m unittest discover -s .agents/skills/pr-status -p 'test_*.py'
"""
import datetime
import pathlib
import tempfile
import unittest
from unittest import mock

import pr_status

SETUP = {"USER": "human", "AGENT": "human-agents",
         "AGENT_FOOTERS": ["Generated by Test Harness", "example.test/agent"],
         "WORK_REPOS": ["owner/work", "org/other"], "MEMORY_REPO": "human/mem",
         "DESIRE_REPO": "human/rules"}
NOW = datetime.datetime(2026, 1, 2, 12, 0, tzinfo=datetime.timezone.utc)
SHA = "a" * 40


def run(name, status="completed", conclusion="success", number=1,
        started="2026-01-02T11:30:00Z"):
    return {"id": number, "name": name, "status": status,
            "conclusion": conclusion, "started_at": started}


def thread(author, body="ok", resolved=False):
    return {"isResolved": resolved, "comments": {"nodes": [
        {"author": {"login": author}, "body": body, "url": f"u/{author}"}]}}


def status(**fields):
    base = {"pr": "owner/work#1", "sha": SHA, "at": "2026-01-02T12:00Z",
            "state": "open", "draft": False, "mergeable": "clean", "ran": True,
            "expected": [],
            "checks": (["build"], [], []), "compare": (0, 1), "todo": None,
            "threads": ([], []), "approval": SHA}
    return {**base, **fields}


class Config(unittest.TestCase):

    def test_lists_split_and_comments_skipped(self):
        with tempfile.TemporaryDirectory() as root:
            path = pathlib.Path(root) / "config.env"
            path.write_text("# seed\nUSER=human\nWORK_REPOS=a/b, c/d\n\n"
                            "AGENT_FOOTERS=x=y,\n")
            setup = pr_status.config(path)
        self.assertEqual(setup["USER"], "human")
        self.assertEqual(setup["WORK_REPOS"], ["a/b", "c/d"])
        self.assertEqual(setup["AGENT_FOOTERS"], ["x=y"])

    def test_a_line_with_no_key_raises(self):
        with tempfile.TemporaryDirectory() as root:
            path = pathlib.Path(root) / "config.env"
            path.write_text("USER\n")
            with self.assertRaises(ValueError):
                pr_status.config(path)


class Checks(unittest.TestCase):

    def test_the_newest_run_of_a_name_wins(self):
        runs = [run("build", conclusion="failure", number=1),
                run("build", number=2)]
        self.assertEqual(pr_status.checks(runs, set(), NOW),
                         (["build"], [], []))

    def test_an_expected_check_never_created_is_pending(self):
        passed, failed, pending = pr_status.checks(
            [run("guard")], {"guard", "build"}, NOW)
        self.assertEqual((passed, failed), (["guard"], []))
        self.assertEqual(pending, ["build never created"])

    def test_a_running_check_carries_its_minutes(self):
        _, _, pending = pr_status.checks(
            [run("build", status="in_progress", conclusion=None)], set(), NOW)
        self.assertEqual(pending, ["build 30m"])

    def test_skipped_passes_and_cancelled_fails(self):
        runs = [run("a", conclusion="skipped", number=1),
                run("b", conclusion="cancelled", number=2)]
        self.assertEqual(pr_status.checks(runs, set(), NOW),
                         (["a"], ["b"], []))


class Threads(unittest.TestCase):

    def test_user_last_waits_on_agent(self):
        self.assertEqual(pr_status.split_threads([thread("human")], SETUP),
                         (["u/human"], []))

    def test_agent_last_waits_on_user(self):
        self.assertEqual(pr_status.split_threads(
            [thread("human-agents")], SETUP), ([], ["u/human-agents"]))

    def test_user_account_with_a_footer_is_the_agent(self):
        body = "Done.\n\nGenerated by Test Harness"
        self.assertEqual(pr_status.split_threads(
            [thread("human", body)], SETUP), ([], ["u/human"]))

    def test_a_footer_label_alone_does_not_count(self):
        body = "Done.\n\n[Generated by Test Harness](https://elsewhere.test)"
        self.assertEqual(pr_status.split_threads(
            [thread("human", body)], SETUP), (["u/human"], []))

    def test_a_reviewer_last_waits_on_agent(self):
        self.assertEqual(pr_status.split_threads([thread("bot")], SETUP),
                         (["u/bot"], []))

    def test_a_deleted_author_waits_on_agent(self):
        unknown = {"isResolved": False, "comments": {"nodes": [
            {"author": None, "body": "?", "url": "u/x"}]}}
        self.assertEqual(pr_status.split_threads([unknown], SETUP),
                         (["u/x"], []))

    def test_resolved_threads_are_skipped(self):
        self.assertEqual(pr_status.split_threads(
            [thread("human", resolved=True)], SETUP), ([], []))

    def test_the_mcp_shape_reads_the_same(self):
        mcp = {"is_resolved": False, "comments": [
            {"author": "human", "body": "?", "html_url": "u/1"},
            {"author": "human-agents", "body": "done", "html_url": "u/2"}]}
        self.assertEqual(pr_status.split_threads([mcp], SETUP), ([], ["u/2"]))


class SavedThreads(unittest.TestCase):

    def answer(self, threads, more):
        return {"review_threads": threads, "pageInfo": {"hasNextPage": more}}

    def test_one_answer_or_its_pages_are_read(self):
        self.assertEqual(pr_status.saved_threads(self.answer([1], False)), [1])
        self.assertEqual(pr_status.saved_threads(
            [self.answer([1], True), self.answer([2], False)]), [1, 2])

    def test_a_missing_page_is_refused(self):
        self.assertIsNone(pr_status.saved_threads(self.answer([1], True)))

    def test_a_bare_list_of_threads_is_read(self):
        self.assertEqual(pr_status.saved_threads([{"is_resolved": True}]),
                         [{"is_resolved": True}])


class Measure(unittest.TestCase):

    def test_a_merged_pull_request_reads_nothing_else(self):
        pull = {"state": "closed", "merged": True, "draft": False,
                "mergeable_state": "unknown", "head": {"sha": SHA},
                "base": {"ref": "main"}, "merged_by": {"login": "human"}}
        paths = []

        def answer(repo, path, key=None):
            paths.append(path)
            return pull
        with mock.patch.object(pr_status, "get", answer):
            s = pr_status.measure("o/r", 1, SETUP, NOW, wait=None)
        self.assertEqual((s["verdict"], paths), ("merged", ["pulls/1"]))
        self.assertTrue(pr_status.line(s).endswith("merged by human"))

    def test_a_todo_that_is_not_utf8_is_still_counted(self):
        pull = {"state": "open", "draft": False, "mergeable_state": "clean",
                "head": {"sha": SHA}, "base": {"ref": "main"}}
        todo = {"content": pr_status.base64.b64encode(b"\xff [ ] a").decode()}

        def answer(repo, path, key=None):
            return {"pulls/1": pull, "contents/TODO.md?ref=" + SHA: todo}.get(path)
        with mock.patch.object(pr_status, "get", answer):
            s = pr_status.measure("o/r", 1, SETUP, NOW, given=[], wait=None)
        self.assertEqual(s["todo"]["open"], 1)


class Main(unittest.TestCase):

    def test_no_target_and_a_bad_config_are_usage_errors(self):
        with tempfile.TemporaryDirectory() as root:
            path = pathlib.Path(root) / "config.env"
            path.write_text("USER=human\n")
            for arguments in ([], ["--config", str(path), "o/r#1"],
                              ["--config", f"{root}/none", "o/r#1"]):
                with self.subTest(arguments=arguments), \
                        mock.patch("sys.stderr"), \
                        self.assertRaises(SystemExit) as stop:
                    pr_status.main(arguments)
                self.assertEqual(stop.exception.code, 2)

    def test_cited_without_repo_is_a_usage_error(self):
        with tempfile.TemporaryDirectory() as root:
            path = pathlib.Path(root) / "config.env"
            path.write_text("USER=human\nAGENT=human-agents\n")
            with mock.patch("sys.stderr"), mock.patch.object(
                    pr_status, "cited", return_value=True), \
                    self.assertRaises(SystemExit) as stop:
                pr_status.main(["--config", str(path), "--cited", str(path)])
        self.assertEqual(stop.exception.code, 2)


class GraphQL(unittest.TestCase):

    def page(self, nodes, more):
        return {"data": {"repository": {"pullRequest": {"reviewThreads": {
            "pageInfo": {"hasNextPage": more, "endCursor": "c"},
            "nodes": nodes}}}}}

    def test_every_page_is_read(self):
        pages = iter([self.page([thread("a")], True),
                      self.page([thread("b")], False)])
        with mock.patch.object(pr_status, "request",
                               lambda *_: next(pages)):
            self.assertEqual(len(pr_status.graphql_threads("o/r", 1)), 2)

    def test_an_error_answer_is_unread(self):
        with mock.patch.object(pr_status, "request",
                               lambda *_: {"message": "not available"}):
            with self.assertRaises(pr_status.Unread):
                pr_status.graphql_threads("o/r", 1)


class RestThreads(unittest.TestCase):

    def answer(self, url, data=None):
        if url.endswith("/ccr/review_threads"):
            return [{"resolved": False, "comment_ids": [1, 2]},
                    {"resolved": True, "comment_ids": [3]}]
        return [{"id": 1, "user": {"login": "rev"}, "body": "fix", "html_url": "u1"},
                {"id": 2, "user": {"login": "human-agents"}, "body": "done", "html_url": "u2"},
                {"id": 3, "user": {"login": "rev"}, "body": "x", "html_url": "u3"}]

    def test_the_last_comment_decides(self):
        with mock.patch.object(pr_status, "request", self.answer):
            found = pr_status.threads("o/r", 1)
        self.assertEqual(pr_status.split_threads(found, SETUP), ([], ["u2"]))

    def test_no_route_falls_back_to_graphql(self):
        def answer(url, data=None):
            if url.endswith("/ccr/review_threads"):
                raise pr_status.Unread("HTTP 403")
            return GraphQL.page(None, [thread("a")], False)
        with mock.patch.object(pr_status, "request", answer):
            self.assertEqual(len(pr_status.threads("o/r", 1)), 1)


class Todo(unittest.TestCase):

    def test_boxes_are_counted(self):
        text = "prompt\n- [ ] a\n- [WIP] @s-2026-01-01 10:00 b\n- [x] c\n- [X] d\n"
        self.assertEqual(pr_status.todo_counts(text),
                         {"open": 1, "wip": 1, "done": 2})


class Approval(unittest.TestCase):

    def review(self, state, sha, user="human"):
        return {"user": {"login": user}, "state": state, "commit_id": sha}

    def test_the_latest_approval_is_read(self):
        self.assertEqual(pr_status.approval(
            [self.review("APPROVED", "old"), self.review("APPROVED", SHA)],
            "human"), SHA)

    def test_changes_requested_after_approval_cancels_it(self):
        self.assertIsNone(pr_status.approval(
            [self.review("APPROVED", SHA),
             self.review("CHANGES_REQUESTED", SHA)], "human"))

    def test_a_comment_review_does_not_cancel(self):
        self.assertEqual(pr_status.approval(
            [self.review("APPROVED", SHA), self.review("COMMENTED", "b")],
            "human"), SHA)

    def test_someone_elses_approval_is_not_users(self):
        self.assertIsNone(pr_status.approval(
            [self.review("APPROVED", SHA, "bot")], "human"))


class Verdict(unittest.TestCase):

    def test_go_needs_approval_on_this_head(self):
        self.assertEqual(pr_status.verdict(status()), ("GO", []))

    def test_an_approval_on_an_older_head_is_ready(self):
        self.assertEqual(pr_status.verdict(status(approval="b" * 40))[0],
                         "ready")

    def test_approved_but_blocked_is_ready(self):
        verdict, reasons = pr_status.verdict(status(mergeable="blocked"))
        self.assertEqual((verdict, reasons), ("ready",
                                              ["approved head but blocked"]))

    def test_dirty_with_no_checks_reads_as_conflict(self):
        verdict, reasons = pr_status.verdict(status(
            mergeable="dirty", ran=False, checks=([], [], [])))
        self.assertEqual(verdict, "waiting-on-agent")
        self.assertEqual(reasons, ["conflict, no checks ran"])

    def test_dirty_with_unread_checks_does_not_say_none_ran(self):
        self.assertEqual(pr_status.verdict(status(
            mergeable="dirty", ran=None, checks="n/a"))[1], ["conflict"])

    def test_pending_and_failed_wait_on_agent(self):
        verdict, reasons = pr_status.verdict(status(
            checks=([], ["lint"], ["build never created"])))
        self.assertEqual(verdict, "waiting-on-agent")
        self.assertEqual(reasons, ["failed lint", "pending build never created"])

    def test_todo_present_waits_on_agent(self):
        self.assertEqual(pr_status.verdict(status(
            todo={"open": 0, "wip": 0, "done": 3}))[0], "waiting-on-agent")

    def test_a_user_thread_waits_on_user(self):
        self.assertEqual(pr_status.verdict(status(threads=([], ["u"])))[0],
                         "waiting-on-USER")

    def test_an_unread_field_is_incomplete_never_go(self):
        for key in ("threads", "checks", "expected", "approval", "compare",
                    "todo"):
            with self.subTest(key=key):
                self.assertEqual(pr_status.verdict(status(**{key: "n/a"}))[0],
                                 "incomplete")

    def test_unknown_mergeable_is_incomplete(self):
        self.assertEqual(pr_status.verdict(status(mergeable="unknown"))[0],
                         "incomplete")

    def test_merged_is_merged(self):
        self.assertEqual(pr_status.verdict(status(state="merged")),
                         ("merged", []))


class Line(unittest.TestCase):

    def test_gate_prints_the_full_sha(self):
        s = status()
        s["verdict"], s["reasons"] = pr_status.verdict(s)
        self.assertIn(f"@{SHA} ", pr_status.line(s, full=True))
        self.assertIn("@aaaaaaa ", pr_status.line(s))
        self.assertTrue(pr_status.line(s).endswith("-> GO"))

    def test_unread_fields_print_na(self):
        s = status(threads="n/a", todo="n/a")
        s["verdict"], s["reasons"] = pr_status.verdict(s)
        self.assertIn("threads n/a; TODO.md n/a", pr_status.line(s))


class Mergeable(unittest.TestCase):

    def test_unknown_is_re_read(self):
        reads = iter([{"state": "open", "mergeable_state": "unknown"},
                      {"state": "open", "mergeable_state": "dirty"}])
        waits = []
        with mock.patch.object(pr_status, "get", lambda *_: next(reads)):
            pull = pr_status.mergeable("o/r", 1, waits.append)
        self.assertEqual((pull["mergeable_state"], waits), ("dirty", [2]))

    def test_re_reads_stop_after_five_reads(self):
        waits = []
        with mock.patch.object(pr_status, "get",
                               lambda *_: {"state": "open", "mergeable_state": "unknown"}):
            pr_status.mergeable("o/r", 1, waits.append)
        self.assertEqual(len(waits), 4)


class Expected(unittest.TestCase):

    def answers(self, table):
        return lambda repo, path: table[path]

    def test_an_unprotected_base_expects_nothing_and_reads_no_rules(self):
        table = {"branches/main": {"protected": False}}
        with mock.patch.object(pr_status, "get", self.answers(table)):
            self.assertEqual(pr_status.expected("o/r", "main"), [])

    def test_protection_and_rulesets_are_joined(self):
        table = {"branches/main": {"protected": True, "protection": {
            "required_status_checks": {"contexts": ["lint"]}}},
                 "rules/branches/main": [{"type": "required_status_checks",
                                          "parameters": {
                                              "required_status_checks": [
                                                  {"context": "build"}]}}]}
        with mock.patch.object(pr_status, "get", self.answers(table)):
            self.assertEqual(pr_status.expected("o/r", "main"),
                             ["build", "lint"])

    def test_null_required_checks_read_as_none(self):
        table = {"branches/main": {"protected": True, "protection": {
            "required_status_checks": None}}, "rules/branches/main": []}
        with mock.patch.object(pr_status, "get", self.answers(table)):
            self.assertEqual(pr_status.expected("o/r", "main"), [])

    def test_an_unreadable_base_is_unread(self):
        table = {"branches/main": None}
        with mock.patch.object(pr_status, "get", self.answers(table)), \
                self.assertRaises(pr_status.Unread):
            pr_status.expected("o/r", "main")


class Cited(unittest.TestCase):

    def test_bare_qualified_and_short_names_resolve(self):
        text = ("a #3 and work#4\nb owner/x#5, other#6 #7/#8\nc unknown#9\n"
                "d other#1 says, #2")
        self.assertEqual(
            [(at, repo, n) for at, _, repo, n in
             pr_status.refs(text, "owner/work", SETUP)],
            [(1, "owner/work", 3), (1, "owner/work", 4), (2, "owner/x", 5),
             (2, "org/other", 6), (2, "org/other", 7), (2, "org/other", 8),
             (4, "org/other", 1), (4, "owner/work", 2)])

    def test_a_bare_number_needs_a_default(self):
        self.assertEqual(list(pr_status.refs("#3", None, SETUP)), [])

    def test_the_words_after_a_citation_stop_at_the_next(self):
        self.assertEqual(
            [words for _, words, _, _ in pr_status.refs(
                "#3 merged, #4 still open", "owner/work", SETUP)],
            [" merged, ", " still open"])

    def test_contradictions(self):
        self.assertTrue(pr_status.contradicts("#3 merged 10-29", "open"))
        self.assertTrue(pr_status.contradicts("#3 still open", "closed"))
        self.assertFalse(pr_status.contradicts("#3 open, #4 merged", "open"))
        self.assertFalse(pr_status.contradicts("#3 waits on #4", "open"))
        self.assertFalse(pr_status.contradicts(" re-merged main", "open"))


if __name__ == "__main__":
    unittest.main()
